import{_ as d,C as o,o as n,c as r,E as a,a4 as i}from"./chunks/framework.BMj-uaUw.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"先回答一个绕不开的问题","slug":"先回答一个绕不开的问题","link":"#先回答一个绕不开的问题","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"这个单元的产出","slug":"这个单元的产出","link":"#这个单元的产出","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit02/index.md","filePath":"unit02/index.md","lastUpdated":1789356894000}'),s={name:"unit02/index.md"};function c(l,t,p,h,g,u){const e=o("UnitMeta");return n(),r("div",null,[a(e,{unit:"单元 2",title:"Node.js 生态、包管理与构建工具",module:"模块一 · 工程化认知与工具链",hours:"4 学时",week:"第 2 周",goals:["会用版本管理工具切换 Node 版本","能读懂 package.json 每个关键字段","能独立排查依赖安装失败问题","能配置一份满足开发与生产需求的 Vite 配置"],outcomes:["依赖排查单","可复用的 vite.config.js"]}),t[0]||(t[0]=i(`<h2 id="先回答一个绕不开的问题" tabindex="-1">先回答一个绕不开的问题 <a class="header-anchor" href="#先回答一个绕不开的问题" aria-label="Permalink to &quot;先回答一个绕不开的问题&quot;">​</a></h2><p>第 1 周你按清单把 Node 装好了。现在问一句：<strong>Node 是干什么的？</strong></p><p>不少同学的回答是“写后端的”。这个印象来自各类 Node 教程 —— 它们教你用 Node 起一个 HTTP 服务、连数据库、写接口。于是就有了下面这段对话。</p><blockquote><p>学生：我又不写后端，为什么要学 Node？ 老师：你上一节课装的 <code>pnpm</code>，是怎么运行的？ 学生：……在命令行里敲的。 老师：命令行里的 <code>pnpm</code>，就是一个用 Node 写的程序。</p></blockquote><p><strong>Node 在这门课里的角色是“工具链的运行环境”</strong>，不是“后端语言的运行环境”。 <code>pnpm</code>、<code>vite</code>、<code>eslint</code>、<code>vitest</code>、<code>tsc</code> —— 这些你每天要用的工具，本质都是 JavaScript 程序，需要有人把它们跑起来。Node 就是那个人。</p><p>这个关系可以类比成 <code>exe</code> 与 Windows：</p><table tabindex="0"><thead><tr><th>类比</th><th>对应到前端</th><th>说明</th></tr></thead><tbody><tr><td>一个 <code>.exe</code> 文件</td><td>一段 JavaScript 工具代码</td><td>程序本身</td></tr><tr><td>双击运行</td><td><code>node xxx.js</code></td><td>需要一个执行环境</td></tr><tr><td>Windows</td><td>Node</td><td>提供执行环境，不是程序本身</td></tr></tbody></table><p>你不必会写字处理软件，但你得有一个操作系统才能打开 <code>.exe</code>。同理，你不必写后端服务， 但你得装 Node 才能跑起 <code>vite</code> 和 <code>pnpm</code>。</p><div class="tip custom-block"><p class="custom-block-title">这个单元要改变的一件事</p><p>第 1 周你装好了工具，但大概率是“照着命令敲，敲完能跑就算过”。 这个单元要把这些工具<strong>从黑盒变成白盒</strong> —— 知道每个配置文件里的每一行在管什么， 报错时能自己定位到是哪一层出了问题。</p><p>这是从“会用”到“能维护”的分界线。也是为什么第 3 周让你自己建项目仓库时， 你能读懂仓库里那些文件，而不是删掉它们。</p></div><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit02/01-node.html">2.1 Node.js 与版本管理</a></td><td>Node 的定位、LTS 与 Current、fnm / nvm、<code>engines</code> 字段</td><td>报错说“Node 版本不对”时怎么处理</td></tr><tr><td><a href="/frontend-engineering-course/unit02/02-package-manager.html">2.2 包管理器与依赖安装</a></td><td>npm / pnpm / yarn 差异、pnpm 的存储机制、幽灵依赖、排查顺序</td><td>安装失败、本地能跑别人报错</td></tr><tr><td><a href="/frontend-engineering-course/unit02/03-package-json.html">2.3 package.json 逐字段精讲</a></td><td>十来个关键字段、语义化版本、<code>^</code> 与 <code>~</code>、锁文件</td><td>读懂项目说明书，管好依赖版本</td></tr><tr><td><a href="/frontend-engineering-course/unit02/04-vite.html">2.4 构建工具与 Vite</a></td><td>为什么需要构建、Vite 两段式工作方式、HMR、与 Webpack 对比</td><td>知道 <code>pnpm dev</code> 背后发生了什么</td></tr><tr><td><a href="/frontend-engineering-course/unit02/05-env-config.html">2.5 环境变量与常用配置</a></td><td><code>.env</code> 文件族、<code>VITE_</code> 前缀、别名、代理、分包</td><td>配出开发与生产都能用的配置</td></tr><tr><td><a href="/frontend-engineering-course/unit02/ai-collaboration.html">AI 协作 · 依赖与版本别交给 AI 记</a></td><td>版本号与包名自己查、配置逐条验证、锁文件不轻删</td><td>让 AI 讲原理，让官方仓库定事实</td></tr><tr><td><a href="/frontend-engineering-course/unit02/practice.html">课后练习</a></td><td>修问题工程、补配置、验证环境变量、分析产物</td><td>把五节知识连起来做一遍</td></tr></tbody></table><p>五节之间是一条线：<strong>运行环境（2.1）→ 装依赖（2.2）→ 管理依赖（2.3）→ 把依赖和源码打包成产物（2.4）→ 区分开发态与生产态的配置（2.5）</strong>。</p><p>每一节都能单独读，但建议按顺序。因为 2.2 的排查顺序要用到 2.1 的版本知识， 2.5 的配置说明要建立在对 2.4 的理解上。</p><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>抽问：<code>pnpm dev</code> 这条命令实际执行了什么？Node 在你机器上还跑了哪些东西？</td></tr><tr><td>讲解</td><td>1.4 学时</td><td>重点讲 2.2 的依赖排查顺序、2.3 的版本范围、2.4 的两段式工作方式</td></tr><tr><td>现场任务</td><td>1.7 学时</td><td>完成练习里的“修问题工程”，当场跑通并记录每一个报错与处理</td></tr><tr><td>复盘</td><td>0.6 学时</td><td>对比各组的“依赖排查单”，看谁的排查顺序更省时间</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这次课最容易卡住的地方</p><p>依赖安装失败。原因通常不在你写的代码里，而在网络、镜像源、Node 版本、缓存这四层。</p><p><strong>不要一遇到报错就删 <code>node_modules</code> 重装。</strong> 删掉重装只是把问题推迟到下一次。 正确做法是按 <a href="/frontend-engineering-course/unit02/02-package-manager.html#依赖装不上时按这个顺序排查">2.2 的排查顺序</a> 一层一层排除，每次只改一个变量，然后记录你改了什么、结果如何。</p></div><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>需要三样东西，第 1 周应该都准备好了。<strong>如果缺，先补上再往下读。</strong></p><ul><li><strong>Node 24 LTS</strong>：<code>node -v</code> 输出类似 <code>v24.9.0</code>。低于 20.19 会在第 4 周开始的 Vue 项目里出问题。</li><li><strong>pnpm 12</strong>：<code>pnpm -v</code> 输出类似 <code>12.4.1</code>。没有的话用 <code>npm i -g pnpm</code> 装。</li><li><strong>一个自己建的练习目录</strong>：不要在桌面随便建，也不要塞进 <code>node_modules</code>。 建议固定在 <code>~/projects/campus-activity-admin</code>，后面几周会一直用这个目录。</li></ul><p>另外准备一个记录文件。这个单元会故意让你遇到报错，<strong>报错处理不了不是问题， 处理完不记下来才是问题</strong>。</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 依赖排查单</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 时间 | 现象（报错原文） | 试了什么 | 结果 | 最终原因 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| --- | --- | --- | --- | --- |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| | | | | |</span></span></code></pre></div><h2 id="这个单元的产出" tabindex="-1">这个单元的产出 <a class="header-anchor" href="#这个单元的产出" aria-label="Permalink to &quot;这个单元的产出&quot;">​</a></h2><p>按课程要求，这次课交两样东西。</p><p><strong>一、依赖排查单</strong></p><p>不是“装了个包”的流水账，而是一份<strong>按排查顺序记录的问题档案</strong>。至少包含：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>现象</td><td>报错原文，完整贴出来，不要只写“报错了”</td></tr><tr><td>排查顺序</td><td>按网络与镜像 → Node 版本 → 权限 → 缓存 → 锁文件的顺序逐项排除</td></tr><tr><td>每次动作</td><td>一次只改一个变量，写清楚改了什么、结果如何</td></tr><tr><td>结论</td><td>最终原因是什么；如果再遇到同类问题，第一步该查哪里</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一份好的排查单长什么样</p><blockquote><p>现象：<code>pnpm install</code> 报 <code>ERR_PNPM_META_FETCH_FAIL</code>。 排查 1：<code>ping registry.npmjs.org</code> 通，说明不是断网。 排查 2：访问公司镜像地址超时 —— <strong>怀疑是镜像源</strong>。 排查 3：<code>pnpm config get registry</code> 输出还是旧的镜像地址。 处理：<code>pnpm config set registry https://registry.npmmirror.com</code>，重装成功。 结论：镜像源失效。这类报错先查 <code>registry</code>，再查网络。</p></blockquote><p>注意它的结构：<strong>每一条都只有“做了什么 → 看到什么”</strong>，没有“可能是”“应该是”这类猜测。</p></div><p><strong>二、可复用的 <code>vite.config.js</code></strong></p><p>一份能直接复制到新项目里用的配置文件，至少包含：</p><table tabindex="0"><thead><tr><th>配置项</th><th>要求</th></tr></thead><tbody><tr><td>路径别名</td><td><code>@</code> 指向 <code>src</code>，并在编辑器里也能识别</td></tr><tr><td>开发代理</td><td>把 <code>/api</code> 转发到后端地址，解决本地跨域</td></tr><tr><td>构建输出</td><td>指定产物目录、资源内联阈值</td></tr><tr><td>代码分包</td><td>把体积大的库拆成独立 chunk，不全部塞进主包</td></tr><tr><td>环境变量</td><td>用到 <code>VITE_</code> 前缀的变量，并在配置里读取</td></tr></tbody></table><p>这份配置是第 11 周搭建综合项目时的起点。<strong>写完先自己跑一遍 <code>pnpm build &amp;&amp; pnpm preview</code>，产物能正常打开才算完成。</strong></p><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>下一单元（<a href="/frontend-engineering-course/unit03/">单元 3</a>）是“第 3 周建项目仓库”的关键节点。第 3 周要做的 工程模板，就是拿这个单元练出来的 <code>vite.config.js</code> 做基础，再往上加代码检查与提交钩子。</p><p>所以这个单元的练习不要糊弄过去。<strong>你在这里多弄懂一个字段，第 3 周就少卡一小时。</strong></p><p>如果时间紧，优先保证 2.2 与 2.5 两节过关，其余两节可以带着问题回看。</p><hr><p>下一节：<a href="/frontend-engineering-course/unit02/01-node.html">2.1 Node.js 与版本管理</a></p>`,37))])}const k=d(s,[["render",c]]);export{b as __pageData,k as default};
